import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { User, LogOut, Edit } from "lucide-react";

import {
  Screen,
  PrimaryButton,
} from "../components/common/UI";

import "../styles/Profile.css";

export default function Profile() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /auth/me
    setUser({
      _id: "1",
      name: "Ngawang Pema",
      username: "ngawang",
      email: "user@gmail.com",
      whatsapp_number: "+61412345678",
      roles: ["payer", "recipient"],
      country: "AU",
      user_image: "https://i.pravatar.cc/100?img=47",
      account_status: "active",
      kyc_status: "verified",
      created_at: "2026-10-01T08:00:00.000Z"
    });
    setLoading(false);
  }, []);

  const handleLogout = () => {
    // TODO: Clear JWT token from storage
    localStorage.removeItem("token");
    navigate("/home");
  };

  if (loading) {
    return <Screen title="My Profile" back>Loading...</Screen>;
  }

  return (
    <Screen title="My Profile" back>
      <div className="profile-card">
        {user?.user_image ? (
          <img
            src={user.user_image}
            alt="Profile"
          />
        ) : (
          <div className="profile-image-placeholder">
            <User size={32} />
          </div>
        )}

        <h2>{user?.name || "User"}</h2>

        <p className="muted">
          @{user?.username || "username"}
        </p>

        <div className="profile-status">
          <span className={`status-badge ${user?.account_status}`}>
            {user?.account_status || "active"}
          </span>
          <span className={`kyc-badge ${user?.kyc_status}`}>
            KYC: {user?.kyc_status || "pending"}
          </span>
        </div>
      </div>

      <button
        className="panel profile-option"
        onClick={() =>
          navigate("/orders")
        }
      >
        <div className="row">
          <span>My Orders</span>
        </div>
        <span>›</span>
      </button>

      <button
        className="panel profile-option"
        onClick={() =>
          navigate("/transactions")
        }
      >
        <div className="row">
          <span>Transaction History</span>
        </div>
        <span>›</span>
      </button>

      <button
        className="panel profile-option"
        onClick={() => {
          // TODO: Implement edit profile
        }}
      >
        <div className="row">
          <Edit size={16} />
          <span>Edit Profile</span>
        </div>
        <span>›</span>
      </button>

      <button
        className="panel profile-option logout"
        onClick={handleLogout}
      >
        <div className="row">
          <LogOut size={16} />
          <span>Sign out of {user?.name || "account"}</span>
        </div>
        <span>›</span>
      </button>
    </Screen>
  );
}
